select json_build_object('stages',to_regclass('public.work_stages') is not null,'stage_kind',exists(select 1 from information_schema.columns where table_schema='public' and table_name='work_stages' and column_name='kind'),'cards',to_regclass('public.work_cards') is not null,'comments',to_regclass('public.work_comments') is not null,'activity_details',exists(select 1 from information_schema.columns where table_schema='public' and table_name='work_activity' and column_name='details'),'comment_insert_only',exists(select 1 from pg_policies where schemaname='public' and tablename='work_comments' and cmd='INSERT') and not exists(select 1 from pg_policies where schemaname='public' and tablename='work_comments' and cmd in ('UPDATE','DELETE','ALL')),'audit_trigger',exists(select 1 from pg_trigger where tgname='work_audit' and not tgisinternal),'work_function',to_regproc('public.change_work_card') is not null,'bucket',exists(select 1 from storage.buckets where id='creatives'));
